"""PHP · Etapa 4: formularios, objetos y composición."""
from ..generador import K

LISTA = [
K("Formularios", d="interfaz que recoge campos y los representa como datos para validar", u="organizar entradas con nombres y comprobar sus valores", mas="Los formularios web envían campos que PHP puede validar y procesar. Para mantener los ejemplos repetibles, aquí se modela el contenido con un arreglo local en vez de leer una petición real.", k=["Los campos de un formulario tienen nombres asociados a sus valores.", "Los datos recibidos deben validarse antes de usarse.", "Un arreglo local permite practicar el manejo de campos sin depender de una petición."], sit="Quieres validar campos de un formulario sin leer datos externos durante el ejemplo; ¿cómo representas las entradas?", cod="<?php $form = ['nombre' => 'Ada']; echo isset($form['nombre']) ? 'recibido' : 'vacío';", h="comprueba si el arreglo local contiene el campo nombre", pr=("Un conjunto local de campos se puede representar con un arreglo ___ .", "asociativo"), ec="confiar en que un campo enviado siempre existe y tiene el formato esperado", pr2=("El ejemplo determina que el campo está ___.", "recibido"), out="recibido"),
K("Clases", d="plantillas que definen propiedades y comportamientos para crear objetos", u="modelar entidades con estado y operaciones relacionadas", mas="Una clase agrupa propiedades y métodos. La palabra new crea una instancia concreta que conserva su propio estado.", k=["class declara una clase.", "new crea una instancia de una clase.", "Los objetos creados desde una clase pueden mantener estados distintos."], sit="Un sistema necesita crear varios productos con propiedades y acciones compartidas; ¿qué plantilla defines?", cod="<?php class Producto { public string $nombre = 'taza'; } $p = new Producto(); echo $p->nombre;", h="define una clase, crea un objeto y lee su propiedad", pr=("La plantilla que declara propiedades y métodos se llama ___.", "clase"), ec="usar una clase como si fuera ya una instancia", pr2=("La propiedad nombre del objeto contiene ___.", "taza"), out="taza"),
K("Constructor", d="método __construct que se ejecuta al crear una instancia", u="inicializar el estado requerido de un objeto", mas="El constructor es un método especial que PHP llama cuando se crea el objeto con new. Puede recibir argumentos y asignarlos a propiedades.", k=["El nombre del constructor PHP es __construct.", "El constructor se ejecuta durante la creación con new.", "Un constructor puede recibir parámetros para inicializar propiedades."], sit="Una instancia debe recibir su nombre al crearse para quedar lista; ¿qué método especial defines?", cod="<?php class Caja { public function __construct(public string $color) {} } echo (new Caja('azul'))->color;", h="inicializa una propiedad al construir el objeto", pr=("El método que inicializa una instancia se llama ___.", "__construct"), ec="llamar manualmente al constructor después de crear el objeto", pr2=("El color almacenado por la instancia es ___.", "azul"), out="azul"),
K("Visibilidad", d="modificadores public, protected y private que controlan el acceso a miembros", u="definir qué código puede leer o cambiar cada miembro", mas="public permite acceso desde cualquier contexto, protected desde la clase y sus descendientes, y private solo dentro de la clase que lo declara. La visibilidad ayuda a proteger invariantes internas.", k=["public permite acceso externo.", "protected es accesible en la clase y sus clases descendientes.", "private limita el acceso a la clase que declara el miembro."], sit="Un saldo interno solo debe consultarse desde métodos de la propia clase; ¿qué visibilidad eliges?", cod="<?php class Cuenta { private int $saldo = 8; public function ver(): int { return $this->saldo; } } echo (new Cuenta())->ver();", h="lee un miembro privado mediante un método público", pr=("El modificador de acceso más restrictivo es ___.", "private"), ec="hacer pública una propiedad interna que debe proteger una regla", pr2=("El método público devuelve un saldo de ___.", "8"), out="8"),
K("Promoción de propiedades", d="sintaxis de constructor que declara y asigna propiedades desde sus parámetros", u="reducir código repetido al inicializar propiedades", mas="PHP 8 permite promocionar parámetros del constructor escribiendo su visibilidad y tipo en la firma. PHP crea la propiedad y asigna automáticamente el argumento al construir el objeto.", k=["La promoción requiere declarar visibilidad en el parámetro.", "El parámetro promocionado se convierte en una propiedad de instancia.", "La sintaxis de promoción de propiedades apareció en PHP 8.0."], sit="Un constructor solo almacena un parámetro tipado como propiedad y quieres evitar una asignación repetida; ¿qué sintaxis usas?", cod="<?php class Punto { public function __construct(public int $x) {} } echo (new Punto(6))->x;", h="crea una propiedad pública desde el parámetro del constructor", pr=("La característica PHP 8 que declara propiedades desde parámetros es la ___.", "promoción"), ec="omitir public, protected o private al promocionar la propiedad", pr2=("La coordenada del punto es ___.", "6"), out="6"),
K("Métodos", d="funciones declaradas dentro de una clase y asociadas a sus objetos", u="definir operaciones que usan o modifican el estado de una instancia", mas="Un método de instancia se invoca mediante -> sobre un objeto. Dentro de un método, $this representa la instancia actual.", k=["Un método se declara dentro de una clase.", "Se invoca un método de instancia con el operador ->.", "$this referencia el objeto actual dentro de un método no estático."], sit="Un objeto debe calcular un dato usando su propiedad interna; ¿dónde implementas esa operación?", cod="<?php class Cuadro { public function area(int $lado): int { return $lado * $lado; } } echo (new Cuadro())->area(3);", h="llama un método de instancia que calcula un área", pr=("Una operación declarada dentro de una clase se llama ___.", "método"), ec="invocar un método de instancia con :: en lugar de sobre el objeto", pr2=("El área calculada en el ejemplo es ___.", "9"), out="9"),
K("Miembros estáticos", d="propiedades o métodos asociados a la clase en vez de a una instancia", u="ofrecer operaciones que no dependen del estado de un objeto", mas="Un método static se invoca mediante NombreClase::metodo(). Dentro de un método estático no existe una instancia implícita disponible mediante $this.", k=["static declara un miembro asociado a la clase.", "El operador :: accede a un método estático.", "$this no está disponible en un método estático."], sit="Una operación de conversión no necesita propiedades de una instancia y se invoca desde la clase; ¿cómo la declaras?", cod="<?php class Conversor { public static function doble(int $n): int { return $n * 2; } } echo Conversor::doble(5);", h="invoca una operación estática directamente desde la clase", pr=("El modificador para un método asociado a la clase es ___.", "static"), ec="usar $this dentro de un método estático", pr2=("La operación estática devuelve ___.", "10"), out="10"),
K("Herencia", d="relación extends que permite a una clase derivada reutilizar otra clase", u="especializar comportamiento compartido entre tipos relacionados", mas="Una clase derivada hereda miembros accesibles de su clase base mediante extends. PHP solo permite una clase padre directa, aunque una clase puede implementar varias interfaces.", k=["extends declara herencia de clase.", "Una clase PHP tiene una sola clase padre directa.", "Una clase puede implementar varias interfaces."], sit="Un tipo de vehículo debe reutilizar las propiedades públicas y protegidas de Vehiculo; ¿qué relación declaras?", cod="<?php class Base { public function tipo(): string { return 'base'; } } class Hija extends Base {} echo (new Hija())->tipo();", h="hereda un método de la clase base", pr=("La palabra clave para derivar de una clase es ___.", "extends"), ec="intentar extender dos clases base a la vez", pr2=("El método heredado devuelve ___.", "base"), out="base"),
K("Sobrescritura", d="redefinición en una subclase de un método heredado compatible", u="especializar una operación para un tipo derivado", mas="Una subclase puede declarar un método con el mismo nombre que uno heredado y reemplazar su implementación. La firma debe respetar las reglas de compatibilidad de tipos de PHP.", k=["Un método de subclase puede sobrescribir uno heredado.", "Una llamada dinámica ejecuta la implementación de la clase real del objeto.", "Las firmas sobrescritas deben ser compatibles."], sit="Una subclase representa una variante que responde de modo especializado al mismo método; ¿qué técnica aplica?", cod="<?php class Animal { public function voz(): string { return '...'; } } class Gato extends Animal { public function voz(): string { return 'miau'; } } echo (new Gato())->voz();", h="ejecuta la implementación especializada del método heredado", pr=("Reemplazar la implementación heredada de un método se llama ___.", "sobrescritura"), ec="cambiar tipos de la firma sobrescrita de forma incompatible", pr2=("La voz específica del gato es ___.", "miau"), out="miau"),
K("Clase abstracta", d="clase que no puede instanciarse directamente y puede declarar métodos abstractos", u="compartir implementación y exigir operaciones a subclases", mas="Una clase abstracta se marca con abstract y no puede construirse directamente. Puede proporcionar métodos concretos y obligar a sus subclases a implementar métodos abstractos.", k=["abstract class no puede instanciarse directamente.", "Una clase abstracta puede contener métodos implementados.", "Una subclase concreta debe implementar los métodos abstractos heredados."], sit="Varios tipos comparten una base, pero cada tipo concreto debe definir su propio cálculo; ¿qué clase creas?", cod="<?php abstract class Figura { abstract public function lados(): int; } class Triangulo extends Figura { public function lados(): int { return 3; } } echo (new Triangulo())->lados();", h="implementa en una subclase el método abstracto de la base", pr=("Una clase no instanciable marcada con abstract es ___.", "abstracta"), ec="intentar crear directamente una instancia de una clase abstracta", pr2=("El triángulo declara ___ lados.", "3"), out="3"),
K("Interfaces", d="contratos que declaran métodos que una clase debe implementar", u="definir capacidades compartidas entre clases no relacionadas", mas="Una interfaz se declara con interface y una clase la adopta mediante implements. Una clase puede implementar varias interfaces y debe proporcionar los métodos exigidos.", k=["interface declara un contrato.", "implements conecta una clase con una interfaz.", "Una clase puede implementar varias interfaces."], sit="Clases distintas deben ofrecer el mismo método sin compartir una clase base; ¿qué contrato declaras?", cod="<?php interface Nombrable { public function nombre(): string; } class Ciudad implements Nombrable { public function nombre(): string { return 'Lima'; } } echo (new Ciudad())->nombre();", h="implementa un contrato de nombre en una clase", pr=("La palabra clave para adoptar un contrato es ___.", "implements"), ec="dejar sin implementar un método requerido por una interfaz", pr2=("El nombre que devuelve la implementación es ___.", "Lima"), out="Lima"),
K("Traits", d="mecanismos que insertan métodos reutilizables en clases sin herencia", u="compartir implementación entre clases distintas", mas="Un trait se declara con trait y se incorpora en una clase con use. No es una clase que pueda instanciarse y no reemplaza el diseño de interfaces para contratos.", k=["trait declara un conjunto reutilizable de métodos.", "use incorpora un trait dentro de una clase.", "Un trait no es una clase padre instanciable."], sit="Dos clases no relacionadas necesitan compartir una implementación pequeña sin crear una clase base; ¿qué mecanismo puedes usar?", cod="<?php trait Etiqueta { public function etiqueta(): string { return 'ok'; } } class Tarea { use Etiqueta; } echo (new Tarea())->etiqueta();", h="incorpora y utiliza un método definido en un trait", pr=("El mecanismo reutilizable que se incorpora con use es un ___.", "trait"), ec="intentar instanciar directamente un trait", pr2=("El método compartido produce ___.", "ok"), out="ok"),
K("Propiedad readonly", d="propiedad tipada que, una vez inicializada, no puede reasignarse", u="mantener inmutable un dato de instancia después de construirla", mas="PHP 8.1 añadió propiedades readonly. Deben tener tipo, se inicializan una vez desde el ámbito permitido y no se pueden modificar después de la inicialización.", k=["Una propiedad readonly debe declararse con tipo.", "readonly para propiedades se añadió en PHP 8.1.", "Una propiedad readonly inicializada no puede reasignarse."], sit="Un identificador de instancia debe fijarse al construir el objeto y no cambiar después; ¿qué modificador usas?", cod="<?php class Ficha { public function __construct(public readonly int $id) {} } echo (new Ficha(9))->id;", h="lee el identificador de una propiedad readonly", pr=("El modificador de propiedad inmutable en PHP 8.1 es ___.", "readonly"), ec="intentar reasignar una propiedad readonly después de construir el objeto", pr2=("El identificador de la ficha es ___.", "9"), out="9"),
K("Enumeraciones", d="tipos enum que limitan un valor a un conjunto finito de casos", u="representar estados permitidos sin depender de cadenas arbitrarias", mas="Los enums puros se introdujeron en PHP 8.1 y declaran casos con nombres. Un caso se usa como Enum::Caso; no es una cadena automáticamente.", k=["enum define un tipo enumerado.", "Los casos se acceden como Estado::Caso.", "Los enums puros no equivalen a cadenas de texto."], sit="Un semáforo solo puede adoptar tres estados nombrados y tipados; ¿qué tipo de PHP 8.1 modela esa opción?", cod="<?php enum Luz { case Verde; case Rojo; } echo Luz::Verde->name;", h="obtiene el nombre del caso de una enumeración pura", pr=("El tipo con un conjunto finito de casos se declara con ___.", "enum"), ec="comparar un caso de enum puro directamente con una cadena", pr2=("El nombre del caso seleccionado es ___.", "Verde"), out="Verde"),
K("Enum con respaldo", d="enum int o string cuyos casos tienen valores escalares explícitos", u="asociar códigos estables a casos enumerados", mas="Un enum con respaldo declara `: string` o `: int` y asigna un valor a cada caso. El atributo ->value obtiene el valor; from y tryFrom permiten convertir valores al caso correspondiente.", k=["Un enum respaldado indica string o int después de dos puntos.", "Cada caso respaldado tiene un valor escalar único.", "->value recupera el valor de respaldo de un caso."], sit="Estados nombrados deben asociarse a códigos textuales fijos; ¿qué variante de enum eliges?", cod="<?php enum Estado: string { case Abierto = 'open'; } echo Estado::Abierto->value;", h="lee el valor textual de respaldo de un caso", pr=("El enum que asocia un escalar a cada caso es un enum con ___.", "respaldo"), ec="leer ->value de un enum puro que no tiene valor de respaldo", pr2=("El código del caso Abierto es ___.", "open"), out="open"),
K("Espacios de nombres", d="declaraciones namespace que agrupan símbolos bajo un nombre", u="evitar colisiones entre clases de distintos componentes", mas="namespace declara el espacio de nombres de un archivo y debe aparecer antes de otro código, salvo declare. Un nombre completo identifica símbolos con barras invertidas.", k=["namespace declara un espacio de nombres.", "Los nombres cualificados usan barras invertidas.", "El espacio de nombres permite clases con el mismo nombre corto en grupos distintos."], sit="Dos componentes necesitan clases con el mismo nombre corto sin colisionar; ¿qué declaración los separa?", cod="<?php namespace Tienda; class Caja {} echo Caja::class;", h="muestra el nombre cualificado de una clase", pr=("La declaración que agrupa nombres de clases es ___.", "namespace"), ec="poner namespace después de declaraciones ejecutables", pr2=("El nombre cualificado mostrado es ___.", "Tienda\\Caja"), out="Tienda\\Caja"),
K("Excepciones y catch", d="objetos lanzados para comunicar situaciones excepcionales y capturados con catch", u="separar el flujo normal del manejo de fallos", mas="throw lanza un objeto Throwable; un bloque catch compatible puede manejarlo. Las excepciones permiten propagar fallos a una capa que conoce cómo responder.", k=["throw lanza un objeto que implementa Throwable.", "catch recibe una excepción del tipo indicado.", "Una excepción no capturada puede terminar la ejecución actual."], sit="Una operación detecta un valor no permitido y su llamador debe decidir cómo manejarlo; ¿qué mecanismo utiliza?", cod="<?php try { throw new RuntimeException('falla'); } catch (RuntimeException $e) { echo 'capturada'; }", h="lanza y captura una excepción del tipo esperado", pr=("El bloque que maneja una excepción se introduce con ___.", "catch"), ec="capturar un tipo que no coincide con la excepción lanzada", pr2=("El bloque de manejo muestra la palabra ___.", "capturada"), out="capturada"),
K("Bloque finally", d="bloque que se ejecuta después de try y catch, haya ocurrido una excepción o no", u="realizar una acción final común a varios resultados", mas="finally se ejecuta después de try y del catch correspondiente, incluso cuando el flujo sale del bloque mediante return. Para gestionar recursos se prefieren abstracciones apropiadas, pero finally sirve para tareas de cierre controladas.", k=["finally sigue al bloque try y sus catch.", "finally se ejecuta tanto si se lanza una excepción como si no.", "Un return desde try no omite la ejecución de finally."], sit="Una acción de cierre debe ocurrir tanto en éxito como en error; ¿qué bloque permite compartirla?", cod="<?php try { echo 'A'; } finally { echo 'B'; }", h="muestra primero el bloque try y luego el bloque final", pr=("El bloque que se ejecuta al terminar try o catch es ___.", "finally"), ec="colocar finally antes de todos los bloques catch", pr2=("El orden de salida de los dos bloques es ___.", "AB"), out="AB"),
K("Fecha inmutable", d="objeto DateTimeImmutable cuyas operaciones producen nuevas instancias", u="calcular fechas sin mutar accidentalmente el valor original", mas="DateTimeImmutable ofrece operaciones de fecha que devuelven un nuevo objeto. No cambia la instancia original, por lo que varios cálculos pueden partir de la misma fecha inicial.", k=["DateTimeImmutable representa una fecha y hora inmutables.", "modify devuelve una nueva instancia en vez de mutar la original.", "Una cadena de fecha explícita evita depender de la hora actual."], sit="Debes calcular el día siguiente sin alterar el objeto de fecha original y sin consultar el reloj; ¿qué clase usas?", cod="<?php $d = new DateTimeImmutable('2024-01-01'); echo $d->modify('+1 day')->format('Y-m-d');", h="calcula una nueva fecha un día después", pr=("La clase de PHP para fechas inmutables se llama ___.", "DateTimeImmutable"), ec="usar DateTime mutable cuando el cálculo debe preservar la fecha original", pr2=("La fecha del día siguiente es ___.", "2024-01-02"), out="2024-01-02"),
K("Tipos de propiedades", d="declaraciones que restringen los valores almacenables en propiedades de instancia", u="hacer explícito el tipo del estado de un objeto", mas="Desde PHP 7.4 las propiedades pueden declarar tipos como int, string o un tipo de clase. Una propiedad tipada no nullable que aún no se inicializó no puede leerse.", k=["Una propiedad puede declarar su tipo antes de su nombre.", "Una propiedad int no acepta una cadena incompatible.", "Una propiedad tipada sin inicializar no debe leerse."], sit="Un contador de instancia debe aceptar enteros y detectar asignaciones incompatibles; ¿qué agregas a la propiedad?", cod="<?php class Marcador { public int $puntos = 0; } echo (new Marcador())->puntos;", h="declara una propiedad tipada e inicializada", pr=("El tipo que se escribe antes del nombre de una propiedad es una declaración de ___.", "tipo"), ec="leer una propiedad tipada antes de inicializarla", pr2=("El valor inicial del marcador es ___.", "0"), out="0"),
]
